function L({registerIndicator:y,nulls:b}){y({id:"oa-atrn",name:"Average True Range Normalized (ATRN)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:2e3,step:1,tooltip:"Number of bars used for the ATR calculation"}],plots:[{key:"atrn",type:"line",title:"ATRN",style:{color:"#ffeb3b",lineWidth:2},priceFormat:{type:"percent"}}],calc(f,A){const r=Math.max(1,Math.floor(Number(A.length)||14)),i=f.length,s=new Array(i).fill(NaN);if(i===0)return{atrn:b(s)};const x=1-1/r,M=1e-10,e=new Array(i).fill(NaN);let o=NaN,l=0,c=1;const d=Math.max(1,10*r),n=[],a=[];for(let t=0;t<i;t++){const h=f[t],m=Number(h.high),u=Number(h.low),p=Number(h.close);if(!Number.isFinite(m)||!Number.isFinite(u)||!Number.isFinite(p))continue;Number.isFinite(o)||(o=p);const R=m-u,F=Math.abs(m-o),T=Math.abs(u-o),k=Math.max(R,F,T);o=p,l=(l*(r-1)+k)/r,c*=x,e[t]=c>M?l/(1-c):l;const g=Math.max(0,t-d+1);for(;n.length>0&&e[n[n.length-1]]<=e[t];)n.pop();for(n.push(t);n[0]<g;)n.shift();for(;a.length>0&&e[a[a.length-1]]>=e[t];)a.pop();for(a.push(t);a[0]<g;)a.shift();const w=e[n[0]],N=e[a[0]];s[t]=N<w?(e[t]-N)/(w-N):.5}return{atrn:b(s)}}})}export{L as default};
